echo "=== fraud-detection error traces ==="; curl -sg 'http://localhost:16686/jaeger/ui/api/traces?service=fraud-detection&tags=%7B%22error%22%3A%22true%22%7D&lookback=2h&limit=5' | python3 -c "
import sys,json
d=json.load(sys.stdin)
data=d.get('data',[])
print('num traces:',len(data))
for t in data[:3]:
    tid=t['traceID']
    for s in t['spans']:
        tags={tag['key']:tag['value'] for tag in s.get('tags',[])}
        if tags.get('error')=='true' or tags.get('otel.status_code')=='ERROR':
            print('--- trace',tid,'op=',s['operationName'])
            for k in ('rpc.method','rpc.service','feature_flag.key','feature_flag.flag_key','otel.status_description','exception.message','exception.type','grpc.status_code','rpc.grpc.status_code'):
                if k in tags: print('   ',k,'=',tags[k])
" 2>/dev/null

echo "=== recent fraud-detection traces, scan for error spans ==="; curl -sg 'http://localhost:16686/jaeger/ui/api/traces?service=fraud-detection&lookback=2h&limit=40' | python3 -c "
import sys,json
d=json.load(sys.stdin)
data=d.get('data',[])
print('num traces:',len(data))
seen=0
for t in data:
    for s in t['spans']:
        tags={tag['key']:tag['value'] for tag in s.get('tags',[])}
        sc=tags.get('otel.status_code') or tags.get('status.code')
        if str(sc).upper() in ('ERROR','2') or tags.get('error') in (True,'true'):
            seen+=1
            if seen<=6:
                print('=== trace',t['traceID'],'op=',s['operationName'])
                for k in sorted(tags):
                    if k in ('rpc.method','rpc.service','feature_flag.key','feature_flag.flag_key','feature_flag.variant','otel.status_description','exception.message','exception.type','exception.stacktrace','rpc.grpc.status_code','error'):
                        v=str(tags[k]); print('    ',k,'=',v[:300])
print('total error spans seen:',seen)
" 2>/dev/null

echo "=== dump resolve/ResolveInt span tags from a fraud-detection trace ==="; curl -sg 'http://localhost:16686/jaeger/ui/api/traces?service=fraud-detection&operation=resolve&lookback=6h&limit=5' | python3 -c "
import sys,json
d=json.load(sys.stdin)
data=d.get('data',[])
print('num traces:',len(data))
for t in data[:3]:
    for s in t['spans']:
        if s['operationName'] in ('resolve','flagd.evaluation.v1.Service/ResolveInt'):
            tags={tag['key']:tag['value'] for tag in s.get('tags',[])}
            print('--- trace',t['traceID'],'op=',s['operationName'])
            for k in sorted(tags):
                print('    ',k,'=',str(tags[k])[:200])
            print()
" 2>/dev/null | head -60

echo "=== all recent fraud-detection trace operations (last 6h) ==="; curl -sg 'http://localhost:16686/jaeger/ui/api/traces?service=fraud-detection&lookback=6h&limit=30' | python3 -c "
import sys,json
d=json.load(sys.stdin)
data=d.get('data',[])
ops={}
flagkeys=set()
for t in data:
    for s in t['spans']:
        ops[s['operationName']]=ops.get(s['operationName'],0)+1
        tags={tag['key']:tag['value'] for tag in s.get('tags',[])}
        for k,v in tags.items():
            if 'flag' in k.lower() and 'key' in k.lower(): flagkeys.add(str(v))
print('operations:',ops)
print('flag keys seen:',flagkeys)
" 2>/dev/null

